**JavaScript to update countdown dynamically:**
```javascript
// Calculate days until next course start (example: 15th of each month)
function updateCourseCountdown() {
  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();

  // Set next course start date (15th of next month)
  let nextStart = new Date(currentYear, currentMonth + 1, 15);

  // If we're past the 15th, move to next month
  if (today.getDate() >= 15) {
    nextStart = new Date(currentYear, currentMonth + 2, 15);
  }

  // Calculate days remaining
  const diffTime = Math.abs(nextStart - today);
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

  document.getElementById('course-countdown').textContent = diffDays + ' days';
}

updateCourseCountdown();
```

